begin;
do $$
declare admin_id uuid:=gen_random_uuid(); jugador uuid:=gen_random_uuid(); fijo uuid; malla uuid; req uuid:=gen_random_uuid(); req2 uuid:=gen_random_uuid(); resp jsonb; resp2 jsonb; neg uuid; fallo boolean; antes integer;
begin
 insert into perfiles values(admin_id,'KUROI');
 insert into personajes values(1,jugador,'Personaje prueba','aprobado');
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 insert into forja_maestra(nombre,tipo,stats,slot_tipo) values('Espada test','armas','{"dano":2,"peso":1.2}','mano') returning id into fijo;
 insert into forja_maestra(nombre,tipo,es_grupo,stats_rango,slot_tipo) values('Malla test','razas',true,'{"vida":{"min":10,"max":15},"ph":{"min":0,"max":0},"peso":{"min":0.1,"max":0.2}}','ninguno') returning id into malla;
 resp:=forja_crear_copias(fijo,'inventario',1,2,'botin',req);
 if (select count(*) from inventario_jugador where forja_id=fijo and personaje_id=1 and user_id=jugador and slot_tipo='mano' and stats='{"dano":2,"peso":1.2}'::jsonb and slot_equipado is null)<>2 then raise exception 'Copias fijas o destino incorrectos'; end if;
 resp2:=forja_crear_copias(fijo,'inventario',1,2,'botin',req);
 if resp<>resp2 or (select count(*) from inventario_jugador where forja_id=fijo)<>2 then raise exception 'Reintento duplicado'; end if;
 resp:=forja_crear_copias(malla,'batalla',null,20,'encuentro',req2);
 if (select count(*) from forja_instancias where forja_id=malla)<>20 then raise exception 'Cantidad de instancias'; end if;
 if exists(select 1 from forja_instancias where forja_id=malla and ((stats->>'vida')::numeric not between 10 and 15 or (stats->>'vida')::numeric<>trunc((stats->>'vida')::numeric) or (stats->>'ph')::numeric<>0 or (stats->>'peso')::numeric not between .1 and .2 or recursos->>'vida'<>stats->>'vida')) then raise exception 'Valores fuera de rango'; end if;
 update forja_maestra set stats='{"dano":999}' where id=fijo;
 if exists(select 1 from inventario_jugador where forja_id=fijo and stats->>'dano'<>'2') then raise exception 'Copia modificada por plantilla'; end if;
 update forja_maestra set stats_rango='{"vida":{"min":20,"max":10}}' where id=malla;
 select count(*) into antes from forja_operaciones;
 fallo:=false;
 begin perform forja_crear_copias(malla,'batalla',null,1,'invalido',gen_random_uuid()); exception when others then fallo:=true; end;
 if not fallo or (select count(*) from forja_operaciones)<>antes then raise exception 'Rango inválido dejó datos parciales'; end if;
 fallo:=false;
 begin perform forja_crear_copias(fijo,'inventario',999,1,'invalido',gen_random_uuid()); exception when others then fallo:=true; end;
 if not fallo then raise exception 'Aceptó destinatario inexistente'; end if;
 fallo:=false;
 begin perform forja_crear_copias(fijo,'inventario',1,3,'botin',req); exception when others then fallo:=true; end;
 if not fallo then raise exception 'Aceptó solicitud reutilizada con otros parámetros'; end if;
 insert into negociaciones_tienda(item_id,user_id) values(fijo,jugador) returning id into neg;
 perform forja_crear_copias(fijo,'inventario',1,1,'Compra',gen_random_uuid(),neg);
 if (select estado from negociaciones_tienda where id=neg)<>'aprobada' then raise exception 'Negociación no aprobada'; end if;
 if (select ubicacion from forja_maestra where id=fijo) is not null then raise exception 'Cambió ubicación de plantilla'; end if;
 perform set_config('request.jwt.claim.sub',jugador::text,true);
 fallo:=false;
 begin perform forja_crear_copias(fijo,'inventario',1,1,'intruso',gen_random_uuid()); exception when insufficient_privilege then fallo:=true; end;
 if not fallo then raise exception 'Aceptó actor no Kuroi'; end if;
end;
$$;
select '10 comprobaciones SQL correctas en base aislada; todos los datos se revierten' as resultado;
rollback;
